sys_variable_value.value:
(function execute(inputs, outputs) {
    var grEnrollment = new GlideRecord("x_1593181_shark_0_enrollment");
    
    if(grEnrollment.get(inputs.id)){
        outputs.enrollment_record = grEnrollment;
    } else{
        outputs.enrollment_record = null;
    }
})(inputs, outputs);

